          [value]="from()['late-pct'] ?? ''"
          (input)="setFrom('late-pct', value($event))"
          (change)="setFrom('late-pct', value($event))"
        />
        <label for="setting-policy-date">Policy date (claims before it round half up; blank for the sheet's today)</label>
        <input
