      }
    } catch {
      this.resubmit = false;
      this.settingsError.set('Could not save the settings.');
    } finally {
      this.savingSettings = false;
    }
    if (this.resubmit) {
      this.resubmit = false;
      await this.saveSettings(e);
    }
  }

